            do ia = 0, 5
               !$acc atomic update
               jmat(idens, mui + ia, nuj + ib) = jmat(idens, mui + ia, nuj + ib) &
                                          + jab(1 + ia + 6*ib)
            end do
         end do
         do id = 0, 2
            do gi = 1, 1
