            v(12,1) = pax*v(8,1) + wpx*v(8,0)
            v(14,1) = pay*v(8,1) + wpy*v(8,0) &
               + 2.0_dp*oo2z*(v(3,1) - rz*v(3,0))
            v(15,1) = paz*v(8,1) + wpz*v(8,0)
            v(16,1) = pay*v(10,1) + wpy*v(10,0)
            v(17,1) = paz*v(10,1) + wpz*v(10,0) &
