            v(20,1) = qcx*v(5,1) + wqx*v(5,0) &
               + 2.0_dp*oo2ze*v(2,0)
            v(26,1) = qcy*v(5,1) + wqy*v(5,0)
            v(28,1) = paz*v(23,1) + wpz*v(23,0)
