            v(26,0) = qcy*v(8,0) + wqy*v(8,1) &
               + 2.0_dp*oo2ze*v(3,1)
            v(34,0) = qcz*v(5,0) + wqz*v(5,1)
            v(35,0) = pay*v(31,0) + wpy*v(31,1)
            v(36,0) = paz*v(31,0) + wpz*v(31,1) &
