            v(37,0) = qcz*v(8,0) + wqz*v(8,1)
            v(38,0) = qcz*v(9,0) + wqz*v(9,1) &
               + 1.0_dp*oo2ze*v(3,1)
            v(39,0) = qcz*v(10,0) + wqz*v(10,1) &
