            v(40,0) = qcz*v(11,0) + wqz*v(11,1)
            v(43,0) = qcz*v(12,0) + wqz*v(12,1)
            v(44,0) = pay*v(36,0) + wpy*v(36,1)
            v(45,0) = paz*v(36,0) + wpz*v(36,1) &
